function valueHash(v) { const s = typeof v === 'string' ? v : JSON.stringify(v || ''); let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0; return 'h' + h.toString(16); }
